def make_trend_prices(n=1500, seed=20, block=60):
    """n + 1 closes in 60-day blocks: half trend (drift 0.3% a day either way, vol 0.8%),
    half chop (no drift, vol 1.6%)."""
    rng = np.random.default_rng(seed)
    r = []
    while len(r) < n:
        if rng.random() < 0.5:
            r += list(rng.choice([-1, 1]) * 0.003 + 0.008 * rng.standard_normal(block))
        else:
            r += list(0.016 * rng.standard_normal(block))
    r = np.array(r[:n])
    return np.round(100 * np.exp(np.concatenate([[0.0], np.cumsum(r)])), 4).tolist()
